// CLI bridge: exposes configured command-line tools as plugin methods, one method per command.
// Commands run from argv templates without a shell (see config.ts for substitution rules).
//
// Instance manifest example (plugins/cli-gh/plugin.json, generated by renderManifest):
//   "run": { "command": ["bun", "../../bridges/cli/src/main.ts"] }
//   "permissions": ["shell"], "provides": { "methods": ["pr.list"] }
// and in me.config.json / me.local.json:
//   "pluginConfig": { "cli-gh": { "commands": { "pr.list": { "argv": ["gh", "pr", "list", "--repo", "{repo}"], ... } } } }
import { definePlugin, type MethodHandler } from "@me/sdk";
import { validateConfig } from "./config.ts";
import { liveChildren, runCommand } from "./run.ts";

// The SDK looks methods up at call time, so this object is filled once config arrives in initialize.
const methods: Record<string, MethodHandler> = {};

const plugin = definePlugin({
  methods,
  onInit(info) {
    const config = validateConfig(info.config);
    for (const [name, cmd] of Object.entries(config.commands)) {
      methods[name] = (params, ctx) =>
        runCommand(name, cmd, params, {
          baseCwd: config.cwd,
          signal: ctx.signal,
          onLine: (line) => ctx.update({ line }),
          envPass: config.envPass,
        });
    }
  },
  onShutdown() {
    for (const child of liveChildren) child.kill("SIGKILL");
  },
});

await plugin.run();
